export function buildReadyChainWalkReminder(taskId: string | null): string {
  const target = taskId === null ? "the task" : taskId;
  const invocation = taskId === null ? "/implement-task" : `/implement-task ${taskId}`;
  return [
    `${target} is now READY. Walk the chain forward per \`CLAUDE.md §Skill-chain semantics\` —`,
    "the principal is NOT the next actor, and READY is not a hand-off point.",
    "",
    "**Required next action (do not end the turn here):**",
    `- Invoke \`${invocation}\` now.`,
    "",
    "**Legitimate halts — stop ONLY if one actually holds, and CITE what makes it hold:**",
    '- The principal explicitly deferred implementation this session ("just plan it",',
    '  "don\'t implement yet", "I\'ll handle the impl"). Quote their words AND',
    "  name which step the quote defers — a request to EXPLAIN defers nothing",
    "  (mt#3855 R8).",
    "- The READY transition itself surfaced a NEW blocking signal.",
    "- The spec states the task is gated on a decision the principal owns. Name the",
    "  reserved category AND cite the reserving ACT — a principal message, an ask",
    "  response, or an option LABEL they picked.",
    "  Agent-authored artifact text is NOT provenance, including the spec criterion",
    "  you are reading it from (mt#3855 R6). Route it through the Ask substrate",
    "  (`asks_create`), not chat prose.",
    "",
    "**Forbidden — each of these ends the turn prematurely:**",
    '- "Next is `/implement-task`. Want me to go, or stop here?"',
    '- "Ready to implement whenever you are."',
    '- "Let me know if you want me to continue."',
    "- Any equivalent request for permission to proceed.",
    "",
    "These rationales are named INVALID in `/plan-task` Step 4 — do not act on them:",
    '"planning is the skill\'s scope, implementation is a separate skill"; "the user might',
    'want to review the gate report first"; "the next move is user-driven".',
  ].join("\n");
}

/** Read the task id from the tool result, falling back to the tool input. */
